from solution import swap_count


def test_issue_example_given():
    """Example requires swap_count("[]][][") == 2."""
    assert swap_count("[]][][") == 2  # 1 + 1 = 2


def test_issue_single_inverted_pair():
    """Minimum swaps for bracket balancing of "][" is 1."""
    assert swap_count("][") == 1  # 0 + 1 = 1


def test_issue_one_swap_middle():
    """Minimum swaps for bracket balancing of "[]][" is 1."""
    assert swap_count("[]][") == 1  # 0 + 1 = 1


def test_issue_alternating_two_swaps():
    """Minimum swaps for bracket balancing of "][][" is 2."""
    assert swap_count("][][") == 2  # 1 + 1 = 2


def test_issue_three_swaps():
    """Minimum swaps for bracket balancing of "[]]][[" is 3."""
    assert swap_count("[]]][[") == 3  # 2 + 1 = 3


def test_issue_large_symmetric():
    """Minimum swaps for bracket balancing of "]]][[[" is 6."""
    assert swap_count("]]][[[") == 6  # 3 + 2 + 1 = 6


def test_contract_empty_string():
    """Balanced empty string needs zero swaps."""
    assert swap_count("") == 0  # 0 + 0 = 0


def test_contract_single_balanced():
    """Balanced "[]" needs zero swaps."""
    assert swap_count("[]") == 0  # 0 + 0 = 0


def test_contract_double_balanced():
    """Balanced "[][]" needs zero swaps."""
    assert swap_count("[][]") == 0  # 0 + 0 = 0


def test_contract_nested_balanced():
    """Balanced "[[]]" needs zero swaps."""
    assert swap_count("[[]]") == 0  # 0 + 0 = 0


def test_contract_longer_balanced():
    """Balanced "[[]][]" needs zero swaps."""
    assert swap_count("[[]][]") == 0  # 0 + 0 = 0
